import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 size 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const ROLE = '예산·회계 담당자';
const INVALID = 'OPENING_BALANCE_INVALID_INPUT';

function amountOf(value: unknown): string {
  const ok =
    (typeof value === 'number' && Number.isFinite(value)) ||
    (typeof value === 'string' && /^-?\d+(\.\d{1,2})?$/.test(value.trim()));
  if (!ok) {
    throw new ApiError(422, INVALID, '이월 금액을 숫자 형식으로 입력해 주세요.');
  }
  return String(value).trim();
}

function idOf(value: unknown, message: string): string {
  const ok =
    (typeof value === 'number' && Number.isInteger(value)) ||
    (typeof value === 'string' && /^\d+$/.test(value.trim()));
  if (!ok) {
    throw new ApiError(422, INVALID, message);
  }
  return String(value).trim();
}

@Controller('api/v1')
export class FnSfr00605Controller {
  @Post('/opening-balances')
  @HttpCode(200)
  async createOpeningBalance(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    if (data['accountItemId'] === undefined || data['accountItemId'] === null || data['accountItemId'] === '') {
      throw new ApiError(422, INVALID, '계정과목을 선택해 주세요.');
    }
    if (data['carryoverAmount'] === undefined || data['carryoverAmount'] === null || data['carryoverAmount'] === '') {
      throw new ApiError(422, INVALID, '이월 금액을 입력해 주세요.');
    }
    const accountItemId = idOf(data['accountItemId'], '계정과목 형식이 올바르지 않습니다.');
    const amount = amountOf(data['carryoverAmount']);
    const hasYear = data['fiscalYear'] !== undefined && data['fiscalYear'] !== null && data['fiscalYear'] !== '';
    const fiscalYear = hasYear ? idOf(data['fiscalYear'], '회계연도 형식이 올바르지 않습니다.') : null;
    return transaction(async (db) => {
      const accounts = await db.query(
        'SELECT account_item_id FROM account_item WHERE account_item_id = CAST(:accountItemId AS bigint)',
        { accountItemId },
      );
      if (accounts.length === 0) {
        throw new ApiError(404, 'ACCOUNT_ITEM_NOT_FOUND', '계정과목이 존재하지 않습니다.');
      }
      if (fiscalYear !== null) {
        const dup = await db.query(
          'SELECT opening_balance_id FROM opening_balance WHERE account_item_id = CAST(:accountItemId AS bigint) AND fiscal_year = CAST(:fiscalYear AS integer)',
          { accountItemId, fiscalYear },
        );
        if (dup.length > 0) {
          throw new ApiError(409, 'INVALID_STATE', '같은 회계연도에 이미 등록된 계정과목입니다.');
        }
      }
      const rows = await db.query(
        `INSERT INTO opening_balance (account_item_id, carryover_amount, status, fiscal_year, created_at, updated_at)
         VALUES (CAST(:accountItemId AS bigint), CAST(:amount AS numeric), '신청', CAST(:fiscalYear AS integer), now(), now())
         RETURNING opening_balance_id AS "openingBalanceId", status AS "status"`,
        { accountItemId, amount, fiscalYear },
      );
      return rows[0];
    });
  }

  @Patch('/opening-balances/:openingBalanceId')
  async updateOpeningBalance(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const openingBalanceId = req.params['openingBalanceId'];
    const data = checks.inputOf(req.body);
    if (data['carryoverAmount'] === undefined || data['carryoverAmount'] === null || data['carryoverAmount'] === '') {
      throw new ApiError(422, INVALID, '이월 금액을 입력해 주세요.');
    }
    const amount = amountOf(data['carryoverAmount']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM opening_balance WHERE opening_balance_id = CAST(:openingBalanceId AS bigint)',
        { openingBalanceId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'OPENING_BALANCE_NOT_FOUND', '이월내역이 존재하지 않습니다.');
      }
      if (rows[0].status === '마감') {
        throw new ApiError(409, 'OPENING_BALANCE_CLOSED', '마감된 이월내역은 수정할 수 없습니다. 마감취소 후 수정해 주세요.');
      }
      await db.execute(
        'UPDATE opening_balance SET carryover_amount = CAST(:amount AS numeric), updated_at = now() WHERE opening_balance_id = CAST(:openingBalanceId AS bigint)',
        { amount, openingBalanceId },
      );
      return { openingBalanceId: Number(openingBalanceId) };
    });
  }

  @Post('/opening-balances/:openingBalanceId/close')
  @HttpCode(200)
  async closeOpeningBalance(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const openingBalanceId = req.params['openingBalanceId'];
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM opening_balance WHERE opening_balance_id = CAST(:openingBalanceId AS bigint)',
        { openingBalanceId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'OPENING_BALANCE_NOT_FOUND', '이월내역이 존재하지 않습니다.');
      }
      if (rows[0].status === '마감') {
        throw new ApiError(409, 'OPENING_BALANCE_ALREADY_CLOSED', '이미 마감된 이월내역입니다.');
      }
      const result = await db.query(
        `UPDATE opening_balance SET status = '마감', updated_at = now() WHERE opening_balance_id = CAST(:openingBalanceId AS bigint) RETURNING status AS "status"`,
        { openingBalanceId },
      );
      return result[0];
    });
  }

  @Post('/opening-balances/:openingBalanceId/cancel-close')
  @HttpCode(200)
  async cancelCloseOpeningBalance(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const openingBalanceId = req.params['openingBalanceId'];
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT status AS "status" FROM opening_balance WHERE opening_balance_id = CAST(:openingBalanceId AS bigint)',
        { openingBalanceId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'OPENING_BALANCE_NOT_FOUND', '이월내역이 존재하지 않습니다.');
      }
      if (rows[0].status !== '마감') {
        throw new ApiError(409, 'OPENING_BALANCE_NOT_CLOSED', '마감 상태가 아닌 이월내역입니다.');
      }
      const result = await db.query(
        `UPDATE opening_balance SET status = '마감취소', updated_at = now() WHERE opening_balance_id = CAST(:openingBalanceId AS bigint) RETURNING status AS "status"`,
        { openingBalanceId },
      );
      return result[0];
    });
  }

  @Get('/opening-balances')
  async listOpeningBalances(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const pageRaw = Number(query['page'] ?? 0);
    const sizeRaw = Number(query['size'] ?? DEFAULT_SIZE);
    if (!Number.isInteger(pageRaw) || pageRaw < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
    }
    const page = pageRaw;
    const size = Math.min(sizeRaw, MAX_SIZE);
    const hasAccount = query['accountItemId'] !== undefined && query['accountItemId'] !== null && query['accountItemId'] !== '';
    const accountItemId = hasAccount ? String(query['accountItemId']) : null;
    if (accountItemId !== null && !/^\d+$/.test(accountItemId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계정과목 형식이 올바르지 않습니다.');
    }
    const hasStatus = query['status'] !== undefined && query['status'] !== null && query['status'] !== '';
    const status = hasStatus ? String(query['status']) : null;
    if (status !== null && !['신청', '마감', '마감취소'].includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '마감 처리 상태 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where =
        'WHERE (CAST(:accountItemId AS bigint) IS NULL OR account_item_id = CAST(:accountItemId AS bigint)) AND (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar))';
      const totals = await db.query(
        `SELECT COUNT(*) AS "total" FROM opening_balance ${where}`,
        { accountItemId, status },
      );
      const items = await db.query(
        `SELECT opening_balance_id AS "openingBalanceId", account_item_id AS "accountItemId", carryover_amount AS "carryoverAmount", status AS "status", fiscal_year AS "fiscalYear"
         FROM opening_balance ${where}
         ORDER BY opening_balance_id DESC
         LIMIT :size OFFSET :offset`,
        { accountItemId, status, size, offset: page * size },
      );
      return { items, page, size, total: Number(totals[0].total) };
    });
  }
}

