import { useState } from 'react';
import type { Row, PageProps } from '../kit';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  NumberInput,
  Select,
  LookupSelect,
  RefName,
  Tiles,
} from '../kit';

type Mode = 'create' | 'edit' | 'close' | 'cancel';

const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감취소', '마감취소'],
];

export default function FnSfr00605Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [accountFilter, setAccountFilter] = useState<number | string>('');
  const [statusFilter, setStatusFilter] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [mode, setMode] = useState<Mode | null>(null);
  const [target, setTarget] = useState<Row | null>(null);
  const [accountItemId, setAccountItemId] = useState<number | string>('');
  const [amount, setAmount] = useState<number | string>('');
  const [fiscalYear, setFiscalYear] = useState<number | string>('');

  const { data, error, reload } = useData(
    () =>
      call<{ items: Row[]; page: number; size: number; total: number }>(
        'GET',
        '/opening-balances',
        role,
        undefined,
        { ...applied, page, size: 20 },
      ),
    [applied, page],
  );

  const items = data ? data.items : [];
  const total = data ? data.total : 0;
  const closedCount = items.filter((r) => r['status'] === '마감').length;
  const pendingCount = items.filter((r) => r['status'] !== '마감').length;

  function search() {
    setPage(0);
    setApplied({ accountItemId: accountFilter, status: statusFilter });
  }

  function reset() {
    setAccountFilter('');
    setStatusFilter('');
    setPage(0);
    setApplied({});
  }

  function openCreate() {
    setTarget(null);
    setAccountItemId('');
    setAmount('');
    setFiscalYear('');
    setMode('create');
  }

  function openRow(kind: Mode, row: Row) {
    setTarget(row);
    setAmount(row['carryoverAmount'] as number);
    setMode(kind);
  }

  function closeDrawer() {
    setMode(null);
    setTarget(null);
  }

  async function submitCreate() {
    if (accountItemId === '') {
      throw new Error('계정과목을 선택해 주세요.');
    }
    if (amount === '') {
      throw new Error('이월 금액을 입력해 주세요.');
    }
    const body: Row = { accountItemId, carryoverAmount: amount };
    if (fiscalYear !== '') {
      body['fiscalYear'] = fiscalYear;
    }
    await call('POST', '/opening-balances', role, body);
    notify('이월내역을 등록했습니다.');
    closeDrawer();
    reload();
  }

  async function submitEdit() {
    if (!target) {
      return;
    }
    if (amount === '') {
      throw new Error('이월 금액을 입력해 주세요.');
    }
    const id = target['openingBalanceId'];
    await call('PATCH', `/opening-balances/${id}`, role, { carryoverAmount: amount });
    notify('이월내역을 수정했습니다.');
    closeDrawer();
    reload();
  }

  async function submitClose() {
    if (!target) {
      return;
    }
    const id = target['openingBalanceId'];
    await call('POST', `/opening-balances/${id}/close`, role, {});
    notify('마감했습니다.');
    closeDrawer();
    reload();
  }

  async function submitCancel() {
    if (!target) {
      return;
    }
    const id = target['openingBalanceId'];
    await call('POST', `/opening-balances/${id}/cancel-close`, role, {});
    notify('마감취소했습니다.');
    closeDrawer();
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>전체 이월내역</h2>
        <Tiles items={[['건수', <Num value={total} />]]} />
      </section>
      <section className="box span-4">
        <h2>마감 완료</h2>
        <Tiles items={[['이 쪽 건수', <Num value={closedCount} />]]} />
      </section>
      <section className="box span-4">
        <h2>마감 대기</h2>
        <Tiles items={[['이 쪽 건수', <Num value={pendingCount} />]]} />
      </section>
      <section className="box span-12">
        <h2>계정별 이월내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="계정과목">
            <LookupSelect
              table="account_item"
              role={role}
              value={accountFilter}
              onChange={setAccountFilter}
              placeholder="전체"
            />
          </Field>
          <Field label="마감 처리 상태">
            <Select
              value={statusFilter}
              onChange={setStatusFilter}
              options={STATUS_OPTIONS}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>
            이월내역 등록
          </button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          rows={items}
          empty="등록된 이월내역이 없습니다."
          columns={[
            {
              key: 'accountItemId',
              label: '계정과목',
              render: (r) => <RefName table="account_item" role={role} value={r['accountItemId']} />,
            },
            {
              key: 'carryoverAmount',
              label: '이월 금액',
              render: (r) => <Num value={r['carryoverAmount']} />,
            },
            { key: 'fiscalYear', label: '회계연도' },
            {
              key: 'status',
              label: '마감 처리 상태',
              render: (r) => <Badge value={r['status']} />,
            },
            {
              key: 'openingBalanceId',
              label: '처리',
              render: (r) => (
                <span>
                  {r['status'] !== '마감' ? (
                    <button type="button" onClick={() => openRow('edit', r)}>
                      수정
                    </button>
                  ) : null}
                  {r['status'] !== '마감' ? (
                    <button type="button" onClick={() => openRow('close', r)}>
                      마감
                    </button>
                  ) : null}
                  {r['status'] === '마감' ? (
                    <button type="button" onClick={() => openRow('cancel', r)}>
                      마감취소
                    </button>
                  ) : null}
                </span>
              ),
            },
          ]}
        />
        <Pager page={page} size={20} total={total} onPage={setPage} />
      </section>
      {mode === 'create' ? (
        <Drawer title="이월내역 등록" onClose={closeDrawer}>
          <Form onSubmit={submitCreate} submit="등록">
            <Field label="계정과목" required>
              <LookupSelect
                table="account_item"
                role={role}
                value={accountItemId}
                onChange={setAccountItemId}
              />
            </Field>
            <Field label="이월 금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label="회계연도">
              <NumberInput value={fiscalYear} onChange={setFiscalYear} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {mode === 'edit' && target ? (
        <Drawer title="이월내역 수정" onClose={closeDrawer}>
          <Form onSubmit={submitEdit} submit="수정">
            <Field label="계정과목">
              <RefName table="account_item" role={role} value={target['accountItemId']} />
            </Field>
            <Field label="이월 금액" required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {mode === 'close' && target ? (
        <Drawer title="이월내역 마감" onClose={closeDrawer}>
          <Form
            onSubmit={submitClose}
            submit="마감"
            note="마감하면 마감취소 전에는 수정할 수 없습니다."
          />
        </Drawer>
      ) : null}
      {mode === 'cancel' && target ? (
        <Drawer title="이월내역 마감취소" onClose={closeDrawer}>
          <Form
            onSubmit={submitCancel}
            submit="마감취소"
            danger
            note="마감을 취소하고 수정할 수 있는 상태로 되돌립니다."
          />
        </Drawer>
      ) : null}
    </div>
  );
}
